#!/usr/bin/env bash
# Homebrew end-to-end test of the formula Hephaestus generates for goreg.
#
# 1. Installs goreg 1.3.10 from the formula currently in magicdrive/homebrew-tap
#    (generated by GoReleaser; read only, pinned to a tap commit).
# 2. Takes the formula Hephaestus generated in <dist>/homebrew/goreg.rb, points
#    its download URLs at the local archives (file://, nothing else changes),
#    runs brew style and brew audit --strict, and upgrades to it.
# 3. Checks the installed binary (--version, a formatting run), the bash and
#    zsh completion files (same place and content as with 1.3.10), bash
#    completion registration, brew test, and brew uninstall.
#
# Everything happens in a throw-away tap that is removed on exit. It refuses to
# run when a formula named goreg is already installed, so a workstation's own
# installation is never touched; intended for CI runners and containers.
#
# Usage: scripts/homebrew-e2e.sh <dist-dir> <tag>   (make e2e-homebrew)
set -euo pipefail
export LC_ALL=C

if [[ $# -ne 2 ]]; then
  echo "usage: $0 <dist-dir> <tag>" >&2
  exit 2
fi
dist="$(cd "$1" && pwd)" tag="$2"
version="${tag#v}"
repo="$(cd "$(dirname "$0")/.." && pwd)"
# The tap's goreg.rb for v1.3.10 ("Brew formula update for goreg version
# v1.3.10"), generated by GoReleaser. Read only.
current_formula="https://raw.githubusercontent.com/magicdrive/homebrew-tap/c032e27321c64c27945994af392fca3885588972/goreg.rb"
current_version=1.3.10
work="$(mktemp -d)"
tap="goreg-e2e/t$RANDOM$RANDOM"

export HOMEBREW_NO_AUTO_UPDATE=1 HOMEBREW_DEVELOPER=1 HOMEBREW_NO_ASK=1 \
  HOMEBREW_NO_INSTALL_CLEANUP=1 HOMEBREW_NO_INSTALLED_DEPENDENTS_CHECK=1 \
  HOMEBREW_NO_ANALYTICS=1 HOMEBREW_NO_ENV_HINTS=1

if brew list --formula goreg >/dev/null 2>&1; then
  echo "error: a formula named goreg is already installed; run this test on a disposable machine" >&2
  exit 1
fi

cleanup() {
  set +e
  brew uninstall --force "$tap/goreg" >/dev/null 2>&1
  brew untap --force "$tap" >/dev/null 2>&1
  rm -rf "$work"
}
trap cleanup EXIT

step() { printf '\n==> %s\n' "$*"; }
fail() { echo "homebrew-e2e: $*" >&2; exit 1; }

prefix="$(brew --prefix)"
bash_file="$prefix/etc/bash_completion.d/goreg"
zsh_file="$prefix/share/zsh/site-functions/_goreg"

check_installed() { # check_installed VERSION
  local out
  out="$("$prefix/bin/goreg" --version)"
  [[ "$out" == "goreg version v$1" ]] || fail "--version printed '$out', want 'goreg version v$1'"
  echo "$out"
  [[ -s "$bash_file" ]] || fail "missing $bash_file"
  [[ -s "$zsh_file" ]] || fail "missing $zsh_file"
  cmp "$bash_file" "$repo/misc/completions/bash/goreg-completion.bash"
  cmp "$zsh_file" "$repo/misc/completions/zsh/_goreg"
  echo "completions: $bash_file, $zsh_file"
}

brew tap-new --no-git "$tap" >/dev/null
formulae="$(brew --repository "$tap")/Formula"

step "goreg $current_version from the tap's current formula (read only)"
curl -fsSL "$current_formula" -o "$formulae/goreg.rb"
grep -q "releases/download/v$current_version/" "$formulae/goreg.rb" || fail "unexpected tap formula"
brew install --formula "$tap/goreg"
check_installed "$current_version"

step "goreg $version: the formula generated by Hephaestus, as it would be published"
generated="$dist/homebrew/goreg.rb"
[[ -f "$generated" ]] || fail "missing $generated (run make e2e-dist)"
cat "$generated"
release_url="https://github.com/magicdrive/goreg/releases/download/$tag/"
[[ "$(grep -c "^      url \"${release_url}goreg_${version}_" "$generated")" == 4 ]] || fail "expected four release URLs for $tag"
cp "$generated" "$formulae/goreg.rb"

step "brew style, brew audit --strict, version inferred from the release URLs"
brew style --formula "$tap/goreg"
brew audit --strict --formula "$tap/goreg"
info="$(brew info --formula "$tap/goreg")"
head -1 <<<"$info"
head -1 <<<"$info" | grep -qF "stable $version" || fail "Homebrew does not infer version $version from the formula"

step "The same formula with local archives"
# Only the download URLs change. Homebrew cannot infer the version from a
# file:// path, so the version it inferred above is written out.
sed -e "s|${release_url}|file://${dist}/|" \
  -e "s|^  license \"MIT\"$|  version \"${version}\"\n  license \"MIT\"|" \
  "$generated" > "$formulae/goreg.rb"
if grep -q 'https://github.com/magicdrive/goreg/releases' "$formulae/goreg.rb"; then fail "a release URL was not rewritten"; fi
grep -qx "  version \"${version}\"" "$formulae/goreg.rb" || fail "version line not added"
diff "$generated" "$formulae/goreg.rb" || true

step "brew upgrade $current_version → $version"
brew upgrade --formula "$tap/goreg"
check_installed "$version"

step "Installed goreg formats a file"
cp "$repo/misc/example.go.txt" "$work/example.go"
"$prefix/bin/goreg" --local github.com/magicdrive/goreg "$work/example.go" | grep -q '^package main'

step "bash completion is registered"
bash --norc --noprofile -c "source '$bash_file' && complete -p goreg" | grep -qx 'complete -F _goreg_completions goreg'
if command -v zsh >/dev/null; then
  zsh -n "$zsh_file"
  echo "zsh: $zsh_file parses"
else
  echo "zsh not installed; syntax check skipped"
fi

step "brew test, brew uninstall"
brew test "$tap/goreg"
# --force: also the 1.3.10 keg kept by HOMEBREW_NO_INSTALL_CLEANUP.
brew uninstall --force "$tap/goreg"
if brew list --formula goreg >/dev/null 2>&1; then fail "goreg is still installed"; fi
[[ ! -e "$prefix/bin/goreg" && ! -e "$bash_file" && ! -e "$zsh_file" ]] || fail "files left behind after uninstall"

echo
echo "Homebrew E2E passed: goreg $current_version (tap) → $version (Hephaestus formula)"
